import{_ as e}from"./chunks/commercial-partners.D-A4-djb.js";import{_ as r,o as l,c as t,a2 as o}from"./chunks/framework.CWgsre3x.js";const f=JSON.parse('{"title":"Εμπορικοί συνεργάτες","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/commercial-partners.md","filePath":"el/plus/commercial-partners.md"}'),i={name:"el/plus/commercial-partners.md"};function s(n,a,c,h,p,m){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="εμπορικοι-συνεργατες" tabindex="-1">Εμπορικοί συνεργάτες <a class="header-anchor" href="#εμπορικοι-συνεργατες" aria-label="Permalink to &quot;Εμπορικοί συνεργάτες&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/commercial-partners.png"><img src="'+e+'" alt="Εμπορικοί συνεργάτες: φίλτρα καταλόγου και μητρώο προμηθειών. Τα ποσοστά είναι ενδεικτικές ρυθμίσεις και όχι συμβατική προσφορά."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Εμπορικοί συνεργάτες: φίλτρα καταλόγου και μητρώο προμηθειών. Τα ποσοστά είναι ενδεικτικές ρυθμίσεις και όχι συμβατική προσφορά.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή.</p><p>Διατηρήστε προφίλ συνεργατών και ελέγξτε εμπορικές συμφωνίες χωρίς να τις συγχέετε με πληρωμές πελατών.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Αναζητήστε ξενοδοχείο, concierge, υπεύθυνο επικοινωνίας ή περιοχή. Φιλτράρετε κατηγορία και ανοίξτε το κατάλληλο εμπορικό προφίλ.</li><li>Με δικαιώματα προσθέστε ή επεξεργαστείτε επωνυμία, κατηγορία, περιοχή, επικοινωνία, προμήθεια και τρόπο διακανονισμού. Ελέγξτε αν η συμφωνία είναι ενεργή ή υπό εξέταση.</li><li>Ελέγξτε συμβατικές τιμές και προμήθειες βάσει συμφωνίας. Καταγράψτε διακανονισμό μόνο με πραγματικά αποδεικτικά και εξουσιοδοτημένη διαδικασία.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Το προφίλ ή η προμήθεια δεν αποδεικνύει υπογεγραμμένη συμφωνία ή εξοφλημένο τιμολόγιο. Μην επινοείτε όρους ούτε διακανονίζετε αμφισβητούμενη εγγραφή.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul><h2 id="αλλαγες-που-περιγραφονται-στην-v0-7-14" tabindex="-1">Αλλαγές που περιγράφονται στην v0.7.14 <a class="header-anchor" href="#αλλαγες-που-περιγραφονται-στην-v0-7-14" aria-label="Permalink to &quot;Αλλαγές που περιγράφονται στην v0.7.14&quot;">​</a></h2><p>Η δημοσιευμένη έκδοση περιγράφει συμβατική τιμολόγηση συνεργατών και απόδοση κρατήσεων σε συνεργάτες. Πριν από την επιβεβαίωση ελέγξτε τον συνεργάτη, τη συμφωνημένη τιμή, την κράτηση και το εξουσιοδοτημένο αποτέλεσμα τιμολόγησης. Η καταγεγραμμένη απόδοση δεν αποδεικνύει υπογεγραμμένη σύμβαση, εξόφληση προμήθειας ή είσπραξη. Η ακριβής διαδικασία και τα δικαιώματα πρέπει να επαληθευτούν στο αποδεκτό περιβάλλον.</p><p>Δείτε <a href="/el/release-notes/">Σημειώσεις εκδόσεων</a>.</p>',19)])])}const _=r(i,[["render",s]]);export{f as __pageData,_ as default};
